import time
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler
import os
import json

global filetype_dict, timestamps
global files, dirs, lengths
dirs = []
files = []
timestamps = {}

root_path = os.path.dirname(os.path.abspath(__file__)).split("/core")[0]

GLOBAL = json.load(open(root_path + '/config.json', 'r'))
# print(GLOBAL)
for r, d, f in os.walk(root_path + "/html"):
    for file in f:
        files.append(os.path.join(r,file))
    for di in d:
        dirs.append(os.path.join(r, di))

for i in files:
   timestamps[i] = time.strftime('%a, %d %b %Y %H:%M:%S %Z', time.gmtime(os.path.getmtime(i)))

for i in dirs:
   timestamps[i] = time.strftime('%a, %d %b %Y %H:%M:%S %Z', time.gmtime(os.path.getmtime(i)))


if GLOBAL['security']['disable_symlink'] == 'True':
    for i in files:
        if os.path.islink(i):
            files.remove(i)
            del timestamps[i]
    for i in dirs:
        if os.path.islink(i):
            dirs.remove(i)
            del timestamps[i]

class watcher:

    watchDirectory = os.path.dirname(os.path.abspath(__file__)).split("/core")[0] + '/html'

    def __init__(self):
        print("[+] Watcher started")
        self.observer = Observer()

    def run(self):
        event_handler = Handler()
        self.observer.schedule(event_handler, self.watchDirectory, recursive = True)
        self.observer.start()
        try:
            while True:
                time.sleep(5)
        except:
            self.observer.stop()
        self.observer.join()

class Handler(FileSystemEventHandler):

    def on_created(self, event):
        if os.path.isfile(event.src_path):
            time.sleep(2)
            files.append(event.src_path)
            timestamps[event.src_path] = time.strftime('%a, %d %b %Y %H:%M:%S %Z', time.gmtime(os.path.getmtime(event.src_path)))
            if GLOBAL['security']['disable_symlink'] == 'True':
                if os.path.islink(event.src_path ):
                    files.remove(event.src_path)
                    del timestamps[event.src_path]
        elif os.path.isdir(event.src_path):
            time.sleep(2)
            dirs.append(event.src_path)
            timestamps[event.src_path] = time.strftime('%a, %d %b %Y %H:%M:%S %Z', time.gmtime(os.path.getmtime(event.src_path)))
            if GLOBAL['security']['disable_symlink'] == 'True':
                if os.path.islink(event.src_path ):
                    files.remove(event.src_path)
                    del timestamps[event.src_path]

    def on_modified(self, event):
        if os.path.isfile(event.src_path):
            time.sleep(2)
            timestamps[event.src_path] = time.strftime('%a, %d %b %Y %H:%M:%S %Z', time.gmtime(os.path.getmtime(event.src_path)))
        elif os.path.isdir(event.src_path):
            time.sleep(2)
            timestamps[event.src_path] = time.strftime('%a, %d %b %Y %H:%M:%S %Z', time.gmtime(os.path.getmtime(event.src_path)))

    def on_deleted(self, event):
        if event.src_path in dirs:
            time.sleep(2)
            dirs.remove(event.src_path)
            del timestamps[event.src_path]
        elif event.src_path in files:
            time.sleep(2)
            files.remove(event.src_path)
            del timestamps[event.src_path]

    def on_moved(self, event):
        if event.src_path in dirs:
            time.sleep(2)
            dirs.remove(event.src_path)
            dirs.append(event.dest_path)
            timestamps[event.dest_path] = time.strftime('%a, %d %b %Y %H:%M:%S %Z', time.gmtime(os.path.getmtime(event.dest_path)))
        elif event.src_path in files:
            time.sleep(2)
            files.remove(event.src_path)
            files.append(event.dest_path)
            timestamps[event.dest_path] = time.strftime('%a, %d %b %Y %H:%M:%S %Z', time.gmtime(os.path.getmtime(event.dest_path)))

