function makeSound(key)
{
    switch(key){
    case "w":
     	var crash= new Audio('sounds/crash.mp3');
     	crash.play();
     	break;
    case "a":
     	var kickBass= new Audio('sounds/kick-bass.mp3');
     	kickBass.play();
     	break;
    case "s":
